SELECT * FROM interview_invitation
WHERE 1=1
AND position_id = #{positionId}
AND status = #{status}
AND candidate_name LIKE CONCAT('%', #{candidateName}, '%')
AND candidate_phone LIKE CONCAT('%', #{candidatePhone}, '%')
AND invited_at >= #{startTime}
AND invited_at <= #{endTime}
ORDER BY invited_at DESC

SELECT * FROM interview_invitation
WHERE application_id = #{applicationId}
ORDER BY invited_at DESC
